                    v=int(min(18,50*(br-0.35)))
                    drive(v+diff//2,v-diff//2,0.6); last=(str(v+diff//2),str(v-diff//2))
                act=f'chase az={baz:.0f} r={br:.2f}'
            elif br<0.22:
                drive(-10,-10,0.4); last=('-10','-10'); act='backoff'
            else:
