            elif back>0.4:
                diff=10 if L>R else -10
                drive(-14-diff//2,-14+diff//2,0.8); last=('x','x'); act=f'escB{diff}'
            else:
                drive(-12,-12,0.5); drive(-8,8,0.5); last=('x','x'); act='escWig'
