                bot.turn_to(bot.H+90*sweep_dir)
                side_left=1.3; phase='side'; act='t90'
            else:
                if phase=='leg':
                    v=int(max(10,min(26,50*(fwd-0.25))))
                    drive(v,v,0.7); last=(str(v),str(v)); act=f'leg{v}'
                else:
                    side_left-=moved*0.001
